.card { font-family: "Segoe UI","Microsoft YaHei",Arial,sans-serif; font-size: 22px;
        text-align: center; color: #23221f; background: #fffdf7; padding: 12px; }
.card img { max-width: 100%; max-height: 62vh; border-radius: 12px; }
.en { font-size: 34px; font-weight: 700; margin: 10px 0 4px; }
.ex { font-size: 22px; color: #5b574c; margin: 6px 0; }
.speaker { font-size: 64px; margin: 40px 0; }
hr#answer { border: 0; border-top: 1px solid #e2ddd0; margin: 14px 0; }
.nightMode.card, .night_mode.card { background: #2a2823; color: #f1eee6; }

.zh-cue { color: #746e63; font-size: 16px; line-height: 1.55; margin: 8px 0 0;
          white-space: pre-line; }
.nightMode .zh-cue, .night_mode .zh-cue { color: #b6afa1; }
.answer-picture .zh-cue { display: none; }

